// Turns the error data of the failed run into a short report for the email.
const { execution = {}, workflow = {} } = $input.first().json;
const error = execution.error ?? {};

const lines = [
  `Workflow: ${workflow.name ?? 'unknown'} (${workflow.id ?? '-'})`,
  `Execution: ${execution.id ?? '-'} (${execution.mode ?? '-'})`,
  `Failed node: ${execution.lastNodeExecuted ?? error.node?.name ?? 'unknown'}`,
  `Message: ${error.message ?? 'no message'}`,
  '',
  `Open the execution: ${execution.url ?? 'not available'}`,
  '',
  error.stack ?? '',
];

console.log(`[error-notification] ${workflow.name}: ${error.message}`);

return [{
  json: {
    subject: `Code à Cuisine: run of "${workflow.name ?? 'workflow'}" failed`,
    text: lines.join('\n'),
  },
}];
